#include "bounce.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <string.h>
static vis_budget budget(void){vis_budget b={{20000000,800000000,300000000},{0,0,0}};return b;}
static FoxDiskScene lights(int color){FoxDiskScene s;FoxDiskLightInput in[3]={0};for(int j=0;j<3;j++){in[j].shape=FOX_DISK_SHAPE_DISK;in[j].center[2]=5;in[j].diameter=.5;in[j].power=10;for(int k=0;k<3;k++)in[j].color[k]=color;}double w[3]={.25,.5,1};assert(fox_disk_scene_init(&s,in,w,1)==FOX_DISK_OK);return s;}
static bounce_triangle attribute(void){bounce_triangle a={0};a.double_sided=1;for(int j=0;j<3;j++){a.v[j].front[2]=32767;a.v[j].back[2]=-32767;a.v[j].a565=a.v[j].b565=0xffff;}return a;}
static vis_scene *planes(double body,double floor,vis_generation gen){double xyz[24];for(int q=0;q<2;q++){double p[12]={-100,-100,q?floor:body,100,-100,q?floor:body,100,100,q?floor:body,-100,100,q?floor:body};memcpy(xyz+q*12,p,sizeof(p));}uint32_t idx[]={0,1,2,0,2,3,4,5,6,4,6,7};vis_limits lim={2048,4095,524288};vis_scene *v=NULL;assert(vis_scene_build(&v,xyz,8,idx,4,gen,lim)==VIS_OK);return v;}
static bounce_scene *build(vis_scene *v,FoxDiskScene *l,bounce_generation g,bounce_ground *ground){bounce_triangle a[4];for(int i=0;i<4;i++)a[i]=attribute();/* Floor placeholders deliberately oppose the relevant outgoing direction and use black rho. */for(int i=2;i<4;i++)for(int j=0;j<3;j++){a[i].v[j].front[2]=a[i].v[j].back[2]=32767;a[i].v[j].a565=a[i].v[j].b565=0;}bounce_scene *s=NULL;assert(bounce_scene_build_ground(&s,v,a,4,l,1,g,262144,ground)==BOUNCE_OK);return s;}
static bounce_result eval(bounce_scene *s,bounce_generation gen,const double p[3],const double n[3],const double rho[3],unsigned outer){bounce_binding b={0};assert(bounce_binding_set(&b,s,gen)==BOUNCE_OK);vis_budget db=budget(),tb=budget();bounce_result r;assert(bounce_eval(&b,gen,p,n,rho,BOUNCE_ONE,outer,16,&db,&tb,&r)==BOUNCE_OK);bounce_binding_clear(&b);return r;}
static void close3(const double a[3],const double b[3]){for(int k=0;k<3;k++)assert(fabs(a[k]-b[k])<1e-12);}
int main(void){bounce_generation g={.visibility={1,1,1},.material=1,.emission=1};bounce_ground ground={.mode=BOUNCE_GROUND_PRIMARY_LE,.object_id=77,.first_triangle=2,.triangle_count=2,.le={.18,2,4}};double p[3]={0,0,0},n[3]={0,0,1},rho[3]={.2,.4,.6},zero[3]={0,0,0},want[3];for(int k=0;k<3;k++)want[k]=rho[k]*ground.le[k];FoxDiskScene l=lights(0);vis_scene *v=planes(-200,1,g.visibility);bounce_scene *s=build(v,&l,g,&ground);
 for(unsigned samples=16;samples<=64;samples*=4){bounce_result r=eval(s,g,p,n,rho,samples);close3(r.combined,want);close3(r.ground,want);close3(r.world,zero);close3(r.bounce,zero);assert(r.counters.primary_ground_hits==samples&&r.counters.primary_ground_emission_hits==samples&&r.counters.primary_hits==samples);assert(!r.counters.secondary_world_rays&&!r.counters.zero_reflection_ns_v);}
 /* Both winding sides emit identically; no shading normal gating or sRGB decode. */double upper[3]={0,0,2},down[3]={0,0,-1};bounce_result r=eval(s,g,upper,down,rho,16);close3(r.combined,want);assert(r.counters.primary_ground_emission_hits==16);
 /* Owned descriptor is not borrowed, and zero Le still counts emission events. */bounce_ground saved=ground;ground.le[0]=99;assert(!bounce_scene_matches_ground(s,&ground));r=eval(s,g,p,n,rho,16);close3(r.combined,want);ground=saved;assert(bounce_scene_matches_ground(s,&ground));
 bounce_binding old={0};assert(bounce_binding_set(&old,s,g)==BOUNCE_OK);bounce_triangle attrs[4];for(int i=0;i<4;i++)attrs[i]=attribute();bounce_scene *before=s;bounce_generation next=g;next.material++;ground.le[0]=.3;assert(bounce_scene_build_ground(&s,v,attrs,4,&l,1,next,262144,&ground)==BOUNCE_GENERATION);assert(s==before);next.emission++;assert(bounce_scene_build_ground(&s,v,attrs,4,&l,1,next,262144,&ground)==BOUNCE_OK);r=eval(old.scene,g,p,n,rho,16);close3(r.combined,want);bounce_binding_clear(&old);
 bounce_binding binding={0};assert(bounce_binding_set(&binding,s,next)==BOUNCE_OK);vis_budget db=budget(),tb=budget();bounce_result sentinel,copy;memset(&sentinel,0x5a,sizeof(sentinel));copy=sentinel;assert(bounce_eval(&binding,g,p,n,rho,BOUNCE_ONE,16,16,&db,&tb,&sentinel)==BOUNCE_GENERATION);assert(!memcmp(&copy,&sentinel,sizeof(copy)));bounce_binding_clear(&binding);
 before=s;bounce_generation future=next;future.emission++;bounce_ground invalid=ground;invalid.first_triangle=UINT32_MAX;assert(bounce_scene_build_ground(&s,v,attrs,4,&l,1,future,262144,&invalid)==BOUNCE_INVALID);invalid=ground;invalid.triangle_count=3;assert(bounce_scene_build_ground(&s,v,attrs,4,&l,1,future,262144,&invalid)==BOUNCE_INVALID);invalid=ground;invalid.object_id=0;assert(bounce_scene_build_ground(&s,v,attrs,4,&l,1,future,262144,&invalid)==BOUNCE_INVALID);invalid=ground;invalid.le[0]=NAN;assert(bounce_scene_build_ground(&s,v,attrs,4,&l,1,future,262144,&invalid)==BOUNCE_INVALID);assert(bounce_scene_build_ground(&s,v,attrs,4,&l,1,future,bounce_scene_required_bytes(4)-1,&ground)==BOUNCE_INVALID);assert(s==before);
 bounce_scene_release(s);ground=saved;ground.mode=BOUNCE_GROUND_CONTROL;s=build(v,&l,g,&ground);r=eval(s,g,p,n,rho,16);close3(r.combined,zero);assert(r.counters.primary_ground_hits==16&&!r.counters.primary_ground_emission_hits);bounce_scene_release(s);
 ground=saved;memset(ground.le,0,sizeof(ground.le));s=build(v,&l,g,&ground);r=eval(s,g,p,n,rho,16);close3(r.combined,zero);assert(r.counters.primary_ground_emission_hits==16);bounce_scene_release(s);
 /* Area sources behind an opaque emitting floor do not shine through it. */l=lights(1);ground=saved;s=build(v,&l,g,&ground);r=eval(s,g,p,n,rho,16);close3(r.direct,zero);close3(r.combined,want);assert(r.counters.primary_direct_queries==48);bounce_scene_release(s);vis_scene_release(v);
 /* Body at +1 reflects downward, but its secondary world rays hit floor at -1.
  * Floor contributes neither its Le nor rho on this secondary path. */l=lights(0);v=planes(1,-1,g.visibility);s=build(v,&l,g,&ground);r=eval(s,g,p,n,rho,16);close3(r.combined,zero);assert(r.counters.primary_ground_hits==0&&r.counters.secondary_ground_hits==256&&r.counters.secondary_world_rays==256);bounce_scene_release(s);vis_scene_release(v);
 /* Legacy wrapper uses canonical groundOFF and emission token zero. */v=planes(-200,-1,g.visibility);g.emission=0;s=NULL;assert(bounce_scene_build(&s,v,attrs,4,&l,1,g,262144)==BOUNCE_OK);assert(bounce_scene_matches_ground(s,NULL));r=eval(s,g,p,n,rho,16);for(int k=0;k<3;k++)want[k]=rho[k]*l.world_radiance[k];close3(r.combined,want);close3(r.ground,zero);assert(!r.counters.primary_ground_hits);bounce_scene_release(s);vis_scene_release(v);
 puts("ground tests passed: primary rho*linearLe, two-sided, world replacement, secondary floor zero, opaque area blocking, descriptor ownership, emission generations, retained lifetime, range and capacity");return 0;}
